export type MybarpoolPluginPdas = {
  config: typeof findConfigPda;
  vault: typeof findVaultPda;
  walletOverride: typeof findWalletOverridePda;
  counter: typeof findCounterPda;
  sponsorship: typeof findSponsorshipPda;
  eventAuthority: typeof findEventAuthorityPda;
};

export type MybarpoolPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function mybarpoolProgram() {
  return <T extends MybarpoolPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { mybarpool: MybarpoolPlugin }> => {
    return extendClient(client, {
      mybarpool: <MybarpoolPlugin>{
        accounts: {
          creatorCounter: addSelfFetchFunctions(client, getCreatorCounterCodec()),
          gameRecord: addSelfFetchFunctions(client, getGameRecordCodec()),
          platformConfig: addSelfFetchFunctions(client, getPlatformConfigCodec()),
          pool: addSelfFetchFunctions(client, getPoolCodec()),
          sponsorship: addSelfFetchFunctions(client, getSponsorshipCodec()),
          walletOverride: addSelfFetchFunctions(client, getWalletOverrideCodec()),
        },
        instructions: {
          buy: (input) => addSelfPlanAndSendFunctions(client, getBuyInstructionAsync(input)),
          cancelPool: (input) =>
            addSelfPlanAndSendFunctions(client, getCancelPoolInstructionAsync(input)),
          closeCounter: (input) =>
            addSelfPlanAndSendFunctions(client, getCloseCounterInstructionAsync(input)),
          closePool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClosePoolInstructionAsync({ ...input, payer: input.payer ?? client.payer }),
            ),
          closeSponsorship: (input) =>
            addSelfPlanAndSendFunctions(client, getCloseSponsorshipInstructionAsync(input)),
          closeWalletOverride: (input) =>
            addSelfPlanAndSendFunctions(client, getCloseWalletOverrideInstructionAsync(input)),
          createGame: (input) =>
            addSelfPlanAndSendFunctions(client, getCreateGameInstructionAsync(input)),
          createPool: (input) =>
            addSelfPlanAndSendFunctions(client, getCreatePoolInstructionAsync(input)),
          draw: (input) => addSelfPlanAndSendFunctions(client, getDrawInstructionAsync(input)),
          initialize: (input) =>
            addSelfPlanAndSendFunctions(client, getInitializeInstructionAsync(input)),
          markGame: (input) =>
            addSelfPlanAndSendFunctions(client, getMarkGameInstructionAsync(input)),
          postScores: (input) =>
            addSelfPlanAndSendFunctions(client, getPostScoresInstructionAsync(input)),
          reclaim: (input) =>
            addSelfPlanAndSendFunctions(client, getReclaimInstructionAsync(input)),
          reclaimSponsorship: (input) =>
            addSelfPlanAndSendFunctions(client, getReclaimSponsorshipInstructionAsync(input)),
          replaceVar: (input) =>
            addSelfPlanAndSendFunctions(client, getReplaceVarInstructionAsync(input)),
          returnBoxes: (input) =>
            addSelfPlanAndSendFunctions(client, getReturnBoxesInstructionAsync(input)),
          returnSponsorship: (input) =>
            addSelfPlanAndSendFunctions(client, getReturnSponsorshipInstructionAsync(input)),
          rotateGateKey: (input) =>
            addSelfPlanAndSendFunctions(client, getRotateGateKeyInstructionAsync(input)),
          sampleVar: (input) =>
            addSelfPlanAndSendFunctions(client, getSampleVarInstructionAsync(input)),
          setVar: (input) => addSelfPlanAndSendFunctions(client, getSetVarInstructionAsync(input)),
          setWalletOverride: (input) =>
            addSelfPlanAndSendFunctions(client, getSetWalletOverrideInstructionAsync(input)),
          settle: (input) => addSelfPlanAndSendFunctions(client, getSettleInstructionAsync(input)),
          split: (input) => addSelfPlanAndSendFunctions(client, getSplitInstructionAsync(input)),
          sponsor: (input) =>
            addSelfPlanAndSendFunctions(client, getSponsorInstructionAsync(input)),
          updateConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateConfigInstructionAsync(input)),
          updateKickoff: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateKickoffInstructionAsync(input)),
        },
        pdas: {
          config: findConfigPda,
          vault: findVaultPda,
          walletOverride: findWalletOverridePda,
          counter: findCounterPda,
          sponsorship: findSponsorshipPda,
          eventAuthority: findEventAuthorityPda,
        },
        identifyAccount: identifyMybarpoolAccount,
        identifyInstruction: identifyMybarpoolInstruction,
        parseInstruction: parseMybarpoolInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
